style.css:
@-moz-document domain("axiom.trade") {
/* Set the GIF as the background */
    body {
        background-image: url('https://i.pinimg.com/originals/e4/80/72/e4807255da9fc1fa2ebb5c8e036434b1.gif');
        background-size: cover;
        background-position: center;
        background-attachment: fixed;
    }

    /* Apply frosted glass effect to the panels */
    .panel-class-name {
        background-color: rgba(255, 255, 255, 0.3); /* Semi-transparent white */
        backdrop-filter: blur(10px); /* Blur effect */
        border-radius: 10px; /* Rounded corners */
        padding: 20px; /* Add some padding */
        border: 1px solid rgba(255, 255, 255, 0.2); /* Light border */
    }

    /* Ensure text inside the panels is readable */
    .panel-class-name h1,
    .panel-class-name h2,
    .panel-class-name h3,
    .panel-class-name p {
        color: #ffffff; /* White text */
        text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.5); /* Text shadow for better readability */
    }
}
